from collections import Counter
def transform(g):
    h,w=len(g),len(g[0])
    cnt=Counter(x for r in g for x in r)
    excl={c for c,_ in cnt.most_common(2)}
    o=[r[:] for r in g]
    for c in cnt:
        if c in excl: continue
        for r in range(h):
            cols=[i for i in range(w) if g[r][i]==c]
            if len(cols)>=2:
                for i in range(min(cols),max(cols)+1):
                    if o[r][i]==0: o[r][i]=c
        for col in range(w):
            rows=[i for i in range(h) if g[i][col]==c]
            if len(rows)>=2:
                for i in range(min(rows),max(rows)+1):
                    if o[i][col]==0: o[i][col]=c
    return o
